const c=require('./scene-contract.assembly.json');
const walk=(o,p)=>{ if(Array.isArray(o)){console.log(p,'[]',o.length); if(o.length&&typeof o[0]==='object')walk(o[0],p+'[0]');}
else if(o&&typeof o==='object'){for(const k of Object.keys(o)){const v=o[k]; if(v&&typeof v==='object')walk(v,p+'.'+k); else console.log(p+'.'+k,'=',JSON.stringify(v).slice(0,120));}}};
