cd /home/thomasphillip/Projects/vox && node -e "
const s=require('./docs/architecture/workflow-orchestration/schemas/paravoxia-scene-contract.schema.json');
function desc(node,path,depth){
 if(depth>6||!node||typeof node!=='object')return;
 const t=node.type;
 let line=path+' :'+(Array.isArray(t)?t.join('|'):t||'');
 if(node.enum)line+=' enum='+JSON.stringify(node.enum);
 if(node.const!==undefined)line+=' const='+JSON.stringify(node.const);
 if(node.pattern)line+=' pat='+node.pattern;
 if(node.required)line+=' REQ='+JSON.stringify(node.required);
 if(node.additionalProperties===false)line+=' [closed]';
 if(node.minimum!==undefined)line+=' min='+node.minimum;
 if(node.maximum!==undefined)line+=' max='+node.maximum;
 console.log(line);
 if(node.properties)for(const k of Object.keys(node.properties))desc(node.properties[k],path+'.'+k,depth+1);
 if(node.items)desc(node.items,path+'[]',depth+1);
}
desc(s,'',0);
" > /tmp/schema-outline.txt; wc -l /tmp/schema-outline.txt; sed -n '1,120p' /tmp/schema-outline.txt

node -e "
const s=require('./docs/architecture/workflow-orchestration/schemas/paravoxia-scene-contract.schema.json');
const defs=s.\$defs||s.definitions||{};
const seen=new Set();
function res(n){while(n&&n.\$ref){const k=n.\$ref.split('/').pop();n=defs[k];}return n;}
function desc(node,path,depth){
 node=res(node); if(!node||typeof node!=='object'||depth>8)return;
 const t=node.type;
 let line='  '.repeat(depth)+path+' :'+(Array.isArray(t)?t.join('|'):t||'');
 if(node.enum)line+=' enum='+JSON.stringify(node.enum);
 if(node.const!==undefined)line+=' const='+JSON.stringify(node.const);
 if(node.pattern)line+=' pat='+node.pattern;
 if(node.required)line+=' REQ='+JSON.stringify(node.required);
 if(node.additionalProperties===false)line+=' [closed]';
 console.log(line);
 if(node.properties)for(const k of Object.keys(node.properties))desc(node.properties[k],k,depth+1);
 if(node.items)desc(node.items,'[]',depth+1);
 if(node.oneOf||node.anyOf)(node.oneOf||node.anyOf).forEach((x,i)=>desc(x,'<alt'+i+'>',depth+1));
}
desc(s,'ROOT',0);
" > /tmp/schema-outline.txt; wc -l /tmp/schema-outline.txt; cat /tmp/schema-outline.txt

